// ========== XSS 防护：输出转义 ==========

// HTML 上下文转义（只能防文本注入，属性/URL/JS 上下文需额外处理）
function escapeHtml(str) {
  const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return str.replace(/[&<>"']/g, c => map[c]);
}

// React JSX 默认转义：安全
text // 自动 HTML 转义
dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(html) }} // 需要 sanitizer

// Vue 模板插值默认转义：安全
// {{ userInput }}
