// ========== CSP 配置 ==========

// Express + Helmet
const helmet = require('helmet');
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'nonce-xxx'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'", 'https://api.example.com'],
    frameAncestors: ["'none'"]
  }
}));

// 每次请求生成新 nonce
const crypto = require('crypto');
app.use((req, res, next) => {
  res.locals.nonce = crypto.randomBytes(16).toString('base64');
  res.setHeader('Content-Security-Policy',
    `default-src 'self'; script-src 'self' 'nonce-${res.locals.nonce}'; connect-src 'self' https://api.example.com`);
  next();
});

// ========== CSRF Token ==========

// 服务端生成 token，嵌入 meta 标签
// <meta name="csrf-token" content="随机token">
const csrfToken = document.querySelector('meta[name="csrf-token"]').content;

fetch('/api/transfer', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrfToken  // 攻击者跨站拿不到这个值
  },
  body: JSON.stringify({ amount: 100 })
});

// ========== SameSite Cookie ==========

// Lax：跨站 POST/PUT/DELETE 不带 Cookie，顶级 GET 导航带
// Strict：所有跨站请求都不带（从外部链接点进来也不带）
// Set-Cookie: session=xxx; HttpOnly; Secure; SameSite=Lax

